//! A log, read as a stream: each entry is decoded as soon as its comma
//! arrives, so memory holds one entry, not the whole file. The same steps as
//! typescript/examples/logs, on the same files.
//! Run: cargo run -p haus-example-logs

/// The types of logs.schema.haus, generated by build.rs.
mod logs {
    haus::include_schema!("logs");
}

use logs::{Entry, Level};
use std::fs::File;
use std::io;

const LOG: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../examples/logs.haus");

fn main() -> Result<(), haus::Error> {
    // 1. Read the stream entry by entry: an iterator over a file (or a socket, or stdin).
    let mut problems = Vec::new();
    for entry in haus::stream::decode::<Entry, _>(File::open(LOG)?) {
        let entry = entry?;
        println!("{}", describe(&entry));
        if is_problem(&entry) {
            problems.push(entry);
        }
    }

    // 2. Write a stream: the problems, one entry per line.
    println!("problems:");
    haus::stream::encode(io::stdout().lock(), &problems)?;
    Ok(())
}

/// One line per entry. Entries of kinds the schema doesn't know are `Unknown`.
fn describe(entry: &Entry) -> String {
    match entry {
        Entry::Log { at, level, service, message } => format!("{} {level:?} {service}: {message}", time(at)),
        Entry::Request { at, method, path, status, ms } => {
            format!("{} {method} {path} → {status} in {ms} ms", time(at))
        }
        Entry::Unknown(other) => format!("(skipped an entry of kind {})", other.tag),
    }
}

fn is_problem(entry: &Entry) -> bool {
    matches!(entry, Entry::Log { level: Level::Warn | Level::Error, .. } | Entry::Request { status: 500.., .. })
}

/// `09:00:02` of `2026-11-11T09:00:02Z`.
fn time(at: &haus::time::Instant) -> &str {
    &at.as_str()[11..19]
}
